def strategy(history, rng):
    n = len(history)
    if n == 0:
        return 'C'
    if n == 1:
        return 'D' if history[0][1] == 'D' else 'C'

    me = [h[0] for h in history]
    op = [h[1] for h in history]
    last_my = me[-1]
    last_opp = op[-1]
    op_c = sum(1 for x in op if x == 'C')
    op_d = n - op_c
    d10 = sum(1 for x in op[-10:] if x == 'D')
    d20 = sum(1 for x in op[-20:] if x == 'D')

    resp_d = 0
    resp_c = 0
    tol = 0
    coopc = 0
    recent_resp_d = 0
    recent_tol = 0
    start = max(1, n - 15)
    for i in range(1, n):
        prev = me[i - 1]
        cur = op[i]
        if prev == 'D':
            resp_d += 1
            if cur == 'C':
                tol += 1
                if i >= start:
                    recent_resp_d += 1
                    recent_tol += 1
        else:
            resp_c += 1
            if cur == 'C':
                coopc += 1

    pD = tol / resp_d if resp_d else 0.0
    pC = coopc / resp_c if resp_c else 1.0

    hostile = op_d == n or (op_d >= max(3, int(0.65 * n))) or (n >= 10 and d10 >= 7)
    if hostile:
        return 'D'

    tolerant = False
    if recent_resp_d >= 3:
        tolerant = recent_tol * 10 >= 7 * recent_resp_d
    elif recent_resp_d >= 1:
        tolerant = (recent_tol == recent_resp_d and (op_c == n or op_c * 5 >= 4 * n or pD >= 0.8))

    if tolerant and not (resp_d >= 2 and me[-2] == 'D' and op[-1] == 'D'):
        return 'D'

    if resp_d >= 3 and resp_c >= 3:
        if pC - pD <= 0.25 and pD >= 0.2:
            return 'D'
        if pC < 0.6 and pD < 0.75:
            return 'D'
    elif resp_c >= 10 and pC < 0.62 and op_d * 5 >= n and op_d * 3 <= n:
        return 'D'

    if last_opp == 'D':
        if last_my == 'C':
            if me[-2] == 'D' and d10 <= 4 and op_c * 2 >= n:
                return 'C'
            return 'D'
        if op_c * 3 >= 2 * n and d10 <= 5:
            return 'C' if rng.random() < 0.65 else 'D'
        return 'D'

    if last_my == 'D':
        if tolerant:
            return 'D'
        return 'C'

    if op_d == 0:
        if n >= 96:
            return 'D'
        if n >= 90 and rng.random() < 0.25:
            return 'D'

    return 'C'
